#include <iostream>
using namespace std;

int main() {
    long long m, b;
    cin >> m >> b;
    long long ans = 0;
    for (long long y = 0; y <= b; ++y) {
        long long x = m * (b - y);
        // sum of integers from 0 to x: x(x+1)/2
        // sum of integers from 0 to y: y(y+1)/2
        long long sum_x = x * (x + 1) / 2;
        long long sum_y = y * (y + 1) / 2;
        // total bananas = sum over rectangle of (i + j)
        // = (y+1)*sum_x + (x+1)*sum_y
        long long total = (y + 1) * sum_x + (x + 1) * sum_y;
        if (total > ans) ans = total;
    }
    cout << ans << "\n";
    return 0;
}
